#!/usr/bin/env tsx
/**
 * No hand-written cap vocabulary (D1050). The vocabulary (D920) is declared on
 * the caps — an action on the method it calls, an event's wording on the
 * event, the rest in the cap's `vocabulary` block — and generated by
 * `npm run codegen` into `packages/types/src/generated/cap-vocabulary.ts`.
 *
 * Fails when a file comes back under the retired
 * `packages/types/src/device/cap-vocabulary/entries/`, when a source file
 * types a value as the map or one of its entries (`CapVocabularyMap`,
 * `CapVocabularyEntry`, `DeviceCapVocabulary`, `SystemCapVocabulary`), and
 * when `vocabulary.ts` stops reading the generated map. Whether the generated
 * file is current is `npm run codegen:check`'s; whether the declarations are
 * complete and true is `check-cap-vocabulary`'s. The judge is
 * `scripts/lib/handwritten-cap-vocabulary.ts`.
 *
 * Usage: npx tsx scripts/check-no-handwritten-cap-vocabulary.ts
 */
import * as fs from 'node:fs'
import * as path from 'node:path'
import {
  findHandwrittenVocabulary,
  type VocabularySourceFile,
} from './lib/handwritten-cap-vocabulary.ts'

const ROOT = path.resolve(import.meta.dirname, '..')
const ROOTS = ['packages', 'server/backend/src']
const SKIP = new Set(['node_modules', 'dist', '.turbo', 'coverage'])

function walk(dir: string, out: VocabularySourceFile[]): void {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (SKIP.has(entry.name) || entry.name.startsWith('.')) continue
    const full = path.join(dir, entry.name)
    if (entry.isDirectory()) walk(full, out)
    else if (/\.tsx?$/.test(entry.name) && !entry.name.endsWith('.d.ts'))
      out.push({ path: path.relative(ROOT, full), text: fs.readFileSync(full, 'utf8') })
  }
}

function main(): void {
  const files: VocabularySourceFile[] = []
  for (const r of ROOTS) walk(path.join(ROOT, r), files)
  const problems = findHandwrittenVocabulary(files)
  if (problems.length > 0) {
    process.stderr.write(`check-no-handwritten-cap-vocabulary: ${problems.length} problem(s)\n`)
    for (const p of problems) process.stderr.write(`  - ${p}\n`)
    process.exit(1)
  }
  process.stdout.write(
    `check-no-handwritten-cap-vocabulary: OK — ${files.length} files, the vocabulary is generated\n`,
  )
}

main()
